def sum(self):
        areas = []
        for shape in self.shapes:
            if isinstance(shape, Square):
                areas.append(math.pow(shape.length, 2))
            elif isinstance(shape, Circle):
                areas.append(math.pi * math.pow(shape.radius, 2))
        return sum(areas)

